/// Run the code at a guest address. `false` if there is none.
pub fn call_addr(a: u32, c: &mut Cpu, m: &mut Mem, h: &mut dyn Host) -> bool {
    match BLOCKS.binary_search_by_key(&a, |e| e.0) {
        Ok(k) => {
            BLOCKS[k].1(c, m, h, a);
            true
        }
        Err(_) => false,
    }
}

/// Every block, ascending, with an identifier for the function
/// it belongs to. The gap to the next block is this one's
/// length, which is what turns a count of block entries into a
/// count of instructions; the identifier is what groups them
/// back into functions. Both are for `xtask engprof`.
pub fn blocks() -> impl Iterator<Item = (u32, usize)> {
    BLOCKS.iter().map(|e| (e.0, e.1 as usize))
}
